source /root/miniconda3/etc/profile.d/conda.sh && conda activate base && f=$(find /root/acr-vla-conformal-refinement/logs/ -name "eval_object_vla_only_seed44*.json" 2>/dev/null | head -1); if [ -n "$f" ]; then echo "=== $f ==="; python3 -c "
import json; d=json.load(open('$f'))
if 'per_task' in d:
    sr=d['overall_success_rate']; pt=d['per_task']
