    print(f'VLA-only seed44: SR={sr*100:.1f}% ({total_s}/{total_r})')
    for k,v in sorted(pt.items()): print(f'  {k}: {v[\"successes\"]}/{v[\"total\"]}')
else:
    first_val=list(d.values())[0]
    if isinstance(first_val, list):
        total=sum(len(v) for v in d.values()); succ=sum(sum(1 for r in v if r.get('success')) for v in d.values())
        print(f'VLA-only seed44: SR={succ/total*100:.1f}% ({succ}/{total})')
"; else echo "NO_JSON_FOUND"; find /root/acr-vla-conformal-refinement/logs/ -name "*vla_only*seed44*" 2>/dev/null; fi
